script:
test("ten percent discount applies only to paid units", function () {
  var actual = code.priceLine({ sku: "A", units: 8, unitPrice: 5 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 40, freeUnits: 2, paidUnits: 6, lineTotal: 27 });
  assert.ok(actual.lineTotal !== 26);
});

test("units under four get only the ten percent discount", function () {
  var actual = code.priceLine({ sku: "A", units: 3, unitPrice: 5 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 15, freeUnits: 0, paidUnits: 3, lineTotal: 13.5 });
});

test("free units are floor of units divided by four and leftovers are charged", function () {
  var actual = code.priceLine({ sku: "A", units: 7, unitPrice: 5 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 35, freeUnits: 1, paidUnits: 6, lineTotal: 27 });
});

test("one unit is waived per complete set of four", function () {
  var actual = code.priceLine({ sku: "A", units: 4, unitPrice: 5 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 20, freeUnits: 1, paidUnits: 3, lineTotal: 13.5 });
});

test("zero units is valid and the line total is zero", function () {
  var actual = code.priceLine({ sku: "A", units: 0, unitPrice: 5 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 0, freeUnits: 0, paidUnits: 0, lineTotal: 0 });
});

test("line total is rounded once at the end half up to two decimals", function () {
  var actual = code.priceLine({ sku: "A", units: 1, unitPrice: 0.05 });
  assert.deepEqual(actual, { sku: "A", normalPrice: 0.05, freeUnits: 0, paidUnits: 1, lineTotal: 0.05 });
});

test("negative units are rejected with an error and no total is returned", function () {
  assert.throws(function () {
    code.priceLine({ sku: "A", units: -1, unitPrice: 5 });
  }, /^invalid field: units$/);
});

test("negative unit price is rejected with an error and no total is returned", function () {
  assert.throws(function () {
    code.priceLine({ sku: "A", units: 1, unitPrice: -1 });
  }, /^invalid field: unitPrice$/);
});
